<template>
  <div class="recipe-workbench" v-loading="loading">
    <div class="workbench-toolbar"><div class="workbench-tabs" role="tablist" aria-label="成本资料"><button v-for="t in tabs" :key="t.id" role="tab" :aria-selected="view===t.id" :class="{active:view===t.id}" @click="view=t.id">{{ t.name }}<span>{{ t.count }}</span></button></div><el-button :loading="loading" @click="load">刷新</el-button></div>
    <p v-if="error" class="workbench-error" role="alert">{{ error }}</p>
    <section class="master-panel">
      <header class="master-toolbar"><div><h3>{{ descriptions[view].title }}</h3><p>{{ descriptions[view].note }}</p></div><div class="master-actions"><el-button v-if="view==='dishes'" :loading="importing" @click="sourceInput.click()">导入成本卡</el-button><el-button v-if="view==='ingredients'" type="primary" @click="ingredientId='new'">新建通用食材</el-button><el-button v-if="view==='packaging'" type="primary" @click="materialForm={}">新建包材</el-button><el-button v-if="view==='schemes'" type="primary" @click="schemeForm={name:'',lines:[],note:''}">新建打包方案</el-button><el-button v-if="['schemes','packaging'].includes(view)" :loading="importing" @click="packingInput.click()">导入包材与方案</el-button></div></header>
      <div class="master-filters"><el-input v-model="search" clearable :placeholder="view==='ingredients'?'搜索通用食材':'搜索名称、规格或编号'" :aria-label="view==='ingredients'?'搜索通用食材':'搜索成本明细'" /><el-select v-if="view==='dishes'" v-model="category" clearable placeholder="全部分类" aria-label="成本分类"><el-option v-for="c in categories" :key="c" :label="c" :value="c" /></el-select><el-select v-if="view==='ingredients'" v-model="kind" clearable placeholder="全部类型"><el-option label="食材" value="食材" /><el-option label="半成品" value="半成品" /></el-select><el-select v-if="view==='dishes'" v-model="status" clearable placeholder="全部维护状态" aria-label="成本维护状态"><el-option label="食材成本待维护" value="food" /><el-option label="打包方案待设置" value="packing" /></el-select><span>{{ filtered.length }} 条</span></div>
      <div class="cost-table-scroll"><table v-if="view==='dishes'" class="cost-table dish-cost-table"><colgroup><col style="width:27%"><col style="width:14%"><col style="width:12%"><col style="width:12%"><col style="width:20%"><col style="width:15%"></colgroup><thead><tr><th>菜品 / 规格</th><th>录入方式</th><th class="numeric">基础成本</th><th class="numeric">打包后成本</th><th>共用打包方案</th><th class="action-cell">操作</th></tr></thead><tbody><tr v-for="m in pageRows" :key="m.id"><td><button class="text-link" @click="editDish(m)">{{ m.name }}</button><small>{{ m.category }} · {{ m.spec || '默认规格' }} · {{ m.skuid || '未编SKU' }}</small></td><td>{{ m.cost_mode==='manual'?'直接录入':'明细组合' }}<small v-if="m.food_cost==null">食材成本待维护</small></td><td class="numeric">{{ amount(m.base_cost) }}</td><td class="numeric"><b>{{ amount(m.packed_cost) }}</b></td><td>{{ m.scheme_name || (m.packaging_status==='none'?'无需额外包材':'待设置') }}</td><td class="action-cell"><el-button link type="primary" @click="editDish(m)">编辑成本与配方</el-button></td></tr></tbody></table>
      <table v-else-if="view==='ingredients'" class="cost-table master-table"><thead><tr><th>通用食材</th><th>类型 / 标准</th><th>单位</th><th class="numeric">单位成本</th><th>计算方式</th><th class="numeric">引用配方</th><th class="action-cell">操作</th></tr></thead><tbody><tr v-for="m in pageRows" :key="m.id"><td><button class="text-link" @click="ingredientId=m.id">{{ m.name }}</button></td><td>{{ m.kind }}<small>{{ m.spec || '通用标准' }}</small></td><td>{{ m.unit }}</td><td class="numeric">{{ price(m.unit_cost) }}</td><td>{{ m.pricing_mode==='recipe'?'通用配方计算':'统一单位成本' }}</td><td class="numeric">{{ m.usage_count }}</td><td class="action-cell"><el-button link type="primary" @click="ingredientId=m.id">维护标准</el-button></td></tr></tbody></table>
      <table v-else-if="view==='packaging'" class="cost-table packaging-table"><colgroup><col style="width:30%"><col style="width:26%"><col style="width:17%"><col style="width:17%"><col style="width:10%"></colgroup><thead><tr><th>包材名称</th><th>采购规格</th><th class="numeric">采购价</th><th class="numeric">换算单件成本</th><th class="action-cell">操作</th></tr></thead><tbody><tr v-for="m in pageRows" :key="m.id"><td><b>{{ m.name }}</b></td><td><template v-if="m.purchase_unit">1 {{ m.purchase_unit }} = {{ m.units_per_purchase }} {{ m.unit }}</template><span v-else class="purchase-pending">待补采购规格</span></td><td class="numeric"><template v-if="m.purchase_price != null">{{ amount(m.purchase_price) }}<small>每 {{ m.purchase_unit }}</small></template><span v-else class="purchase-pending">待填写</span></td><td class="numeric"><b>{{ amount(m.unit_cost) }}</b><small>每 {{ m.unit }}</small></td><td class="action-cell"><el-button link type="primary" @click="materialForm={...m}">维护采购</el-button></td></tr></tbody></table>
      <table v-else-if="view==='schemes'" class="cost-table schemes-table"><colgroup><col style="width:10%"><col style="width:35%"><col style="width:17%"><col style="width:20%"><col style="width:18%"></colgroup><thead><tr><th>编号</th><th>打包方案</th><th class="numeric">包材成本</th><th class="numeric">关联菜品</th><th class="action-cell">操作</th></tr></thead><tbody><tr v-for="s in pageRows" :key="s.id"><td class="scheme-code">{{ s.code || '自建' }}</td><td><button class="text-link" @click="schemeForm=s">{{ s.name }}</button></td><td class="numeric"><b>{{ amount(s.unit_cost) }}</b></td><td class="numeric"><button class="text-link scheme-linked-count" :aria-label="`查看${s.name}关联菜品`" @click="openLinkedDishes(s)">{{ schemeDishes(s.id).length }} 个规格</button></td><td class="action-cell"><el-button link type="primary" @click="schemeForm=s">编辑方案</el-button></td></tr></tbody></table>
      </div>
      <el-empty v-if="!filtered.length" description="暂无匹配明细" :image-size="50" /><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[10,20,50]" :total="filtered.length" layout="total, sizes, prev, pager, next, jumper" class="cost-pagination" />
      <p v-if="data.packaging_import && ['schemes','packaging'].includes(view)" class="source-caption">已导入包材单价与标准方案；菜品对应关系统一在菜品总览的“配方与成本”内维护。</p>
    </section>
    <input ref="sourceInput" type="file" accept=".xlsx" hidden @change="importFile($event,false)" /><input ref="packingInput" type="file" accept=".xlsx" hidden @change="importFile($event,true)" />
    <el-dialog v-model="dishVisible" :title="'编辑菜品成本 · '+(dishItem?.name || '')" width="min(1220px, calc(100vw - 32px))" align-center :before-close="closeDish" class="cost-dish-dialog" destroy-on-close append-to-body><MenuItemRecipePanel v-if="dishVisible && dishItem" :key="dishItem.id" ref="dishEditor" :variants="[{sourceId:dishItem.id,spec:dishItem.spec,skuid:dishItem.skuid}]" @saved="load" /><template #footer><el-button @click="closeDish()">关闭</el-button></template></el-dialog>
    <el-drawer v-model="linkedVisible" :title="'关联菜品 · '+(linkedScheme?.name || '')" size="min(960px, 96vw)" append-to-body class="linked-dishes-drawer"><p class="linked-dishes-note">共 {{ linkedDishes.length }} 个菜品规格使用此方案。点击菜品可查看食材构成、成本及打包设置。</p><el-input v-model="linkedSearch" placeholder="搜索菜名、分类、规格或SKU" aria-label="搜索关联菜品" clearable class="linked-dishes-search" /><div class="cost-table-scroll"><table class="cost-table linked-dishes-table"><colgroup><col style="width:25%"><col style="width:15%"><col style="width:14%"><col style="width:20%"><col style="width:13%"><col style="width:13%"></colgroup><thead><tr><th>菜品名称</th><th>分类</th><th>规格</th><th>SKU编码</th><th class="numeric">基础成本</th><th class="numeric">打包后成本</th></tr></thead><tbody><tr v-for="d in linkedPageRows" :key="d.id"><td><button class="text-link" @click="editDish(d)">{{ d.name }}</button></td><td>{{ d.category }}</td><td>{{ d.spec || '默认规格' }}</td><td class="scheme-code">{{ d.skuid || '未编SKU' }}</td><td class="numeric">{{ amount(d.base_cost) }}</td><td class="numeric">{{ amount(d.packed_cost) }}</td></tr></tbody></table></div><el-empty v-if="!filteredLinkedDishes.length" description="暂无匹配的关联菜品" :image-size="50" /><el-pagination v-model:current-page="linkedPage" v-model:page-size="linkedSize" :page-sizes="[10,20,50]" :total="filteredLinkedDishes.length" layout="total, sizes, prev, pager, next" class="cost-pagination" /><template #footer><el-button @click="linkedVisible=false">关闭列表</el-button></template></el-drawer>
    <MenuIngredientEditor :material-id="ingredientId" :ingredients="data.ingredients" @close="ingredientId=''" @saved="standardsSaved" />
    <MenuPackagingSchemeEditor :scheme="schemeForm" :materials="data.packaging_materials" @close="schemeForm=null" @saved="standardsSaved" />
    <MenuPackagingMaterialEditor :material="materialForm" @close="materialForm=null" @saved="standardsSaved" />
  </div>
</template>
<script setup>
import {computed,inject,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {routeLocationKey} from 'vue-router'
import {ElMessage} from 'element-plus'
import {menuCostRecipesApi as api} from '@/api'
import MenuPackagingMaterialEditor from './MenuPackagingMaterialEditor.vue'
import MenuIngredientEditor from './MenuIngredientEditor.vue'
import MenuItemRecipePanel from './MenuItemRecipePanel.vue'
import MenuPackagingSchemeEditor from './MenuPackagingSchemeEditor.vue'
import { moneyText, moneyAmount } from './moneyDisplay'
const route=inject(routeLocationKey,null)
const data=ref({dishes:[],ingredients:[],packaging_materials:[],packaging_schemes:[],packaging_import:null}),view=ref('dishes'),search=ref(''),category=ref(''),kind=ref(''),status=ref(''),loading=ref(false),error=ref(''),page=ref(1),size=ref(10),ingredientId=ref(''),schemeForm=ref(null),materialForm=ref(null),sourceInput=ref(null),packingInput=ref(null),importing=ref(false),dishVisible=ref(false),dishItem=ref(null),dishEditor=ref(null)
const descriptions={dishes:{title:'菜品成本明细',note:'与菜品总览使用同一份菜品档案，可在这里或总览内直接编辑成本与配方。基础成本含每次出品耗材。'},ingredients:{title:'通用食材标准',note:'统一维护原料单价和半成品配方，菜品引用标准并填写用量。'},packaging:{title:'包材档案',note:'按采购单位、内含数量和采购价换算单件成本，关联打包方案与菜品同步更新。'},schemes:{title:'共用打包方案',note:'维护组合及数量，所有渠道共用。菜品总览里直接选择对应方案。'}}
const tabs=computed(()=>[{id:'dishes',name:'菜品成本明细',count:data.value.dishes.length},{id:'ingredients',name:'通用食材',count:data.value.ingredients.length},{id:'packaging',name:'包材档案',count:data.value.packaging_materials.length},{id:'schemes',name:'打包方案',count:data.value.packaging_schemes.length}])
const categories=computed(()=>[...new Set(data.value.dishes.map(d=>d.category))])
const filtered=computed(()=>{const source=({dishes:data.value.dishes,ingredients:data.value.ingredients,packaging:data.value.packaging_materials,schemes:data.value.packaging_schemes})[view.value];return source.filter(m=>(!search.value||[m.name,m.spec,m.code,m.variant,m.skuid].filter(Boolean).join(' ').includes(search.value.trim()))&&(view.value!=='dishes'||(!category.value||m.category===category.value)&&(!status.value||(status.value==='food'?m.food_cost==null:m.packaging_status==='pending')))&&(view.value!=='ingredients'||!kind.value||m.kind===kind.value))})
const pageRows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value))
const amount=n=>moneyAmount(n,'待维护'),price=n=>moneyText(n,'待补齐')
const linkedVisible=ref(false),linkedSchemeId=ref(''),linkedSearch=ref(''),linkedPage=ref(1),linkedSize=ref(10)
const schemeDishes=id=>data.value.dishes.filter(d=>d.packaging_scheme_id===id)
const linkedScheme=computed(()=>data.value.packaging_schemes.find(s=>s.id===linkedSchemeId.value))
const linkedDishes=computed(()=>schemeDishes(linkedSchemeId.value))
const filteredLinkedDishes=computed(()=>linkedDishes.value.filter(d=>[d.name,d.category,d.spec,d.skuid].filter(Boolean).join(' ').includes(linkedSearch.value.trim())))
const linkedPageRows=computed(()=>filteredLinkedDishes.value.slice((linkedPage.value-1)*linkedSize.value,linkedPage.value*linkedSize.value))
function openLinkedDishes(s){linkedSchemeId.value=s.id;linkedSearch.value='';linkedPage.value=1;linkedVisible.value=true}
watch([linkedSearch,linkedSize],()=>linkedPage.value=1)
watch(()=>filteredLinkedDishes.value.length,n=>linkedPage.value=Math.min(linkedPage.value,Math.max(1,Math.ceil(n/linkedSize.value))))
async function load(){loading.value=true;error.value='';try{data.value=await api.dishes();page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/size.value)))}catch(e){error.value=e.message}finally{loading.value=false}}
function editDish(m){dishItem.value=m;dishVisible.value=true}
async function closeDish(done){if(!dishEditor.value||await dishEditor.value.canLeave()){if(typeof done==='function')done();else dishVisible.value=false}}
function standardsSaved(){window.dispatchEvent(new Event('menu-cost-standards-changed'))}
watch([view,search,category,kind,status,size],()=>{page.value=1})
watch(view,()=>{search.value='';category.value='';status.value=''})
async function importFile(event,packing){const file=event.target.files[0];event.target.value='';if(!file)return;importing.value=true;error.value='';try{const r=await(packing?api.importPackaging(file):api.import(file));await standardsSaved();ElMessage.success(packing?`已读取${r.materials}项包材、${r.schemes}种方案和${r.mappings}条对应记录`:'成本卡已导入，已保存的菜品成本保留');if(packing)view.value='schemes'}catch(e){error.value=e.message}finally{importing.value=false}}
onBeforeUnmount(()=>window.removeEventListener('menu-cost-standards-changed',load))
onMounted(async()=>{window.addEventListener('menu-cost-standards-changed',load);await load();const id=Number(route?.query?.menu_item_id);if(id){const item=data.value.dishes.find(d=>d.id===id);if(item)editDish(item)}})
</script>
<style scoped>
.recipe-workbench{font-size:13px;min-width:0;width:100%;color:#435771}.workbench-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid #e3e9f1;margin-bottom:20px}.workbench-tabs{display:flex;gap:22px;overflow:auto;min-width:0}.workbench-tabs button{display:flex;align-items:center;gap:7px;background:none;border:0;border-bottom:2px solid transparent;padding:14px 0;color:#718198;font-size:13px;cursor:pointer;white-space:nowrap}.workbench-tabs button.active{color:#2563b8;border-color:#2563b8;font-weight:600}.workbench-tabs button span{font-size:10px;background:#edf1f6;border-radius:3px;padding:1px 5px;color:#8290a5}.master-panel{background:#fff;border:1px solid #e3e9f1;border-radius:8px;padding:22px 24px;min-width:0}.master-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:18px}.master-toolbar h3{margin:0;font-size:17px;color:#2a405f}.master-toolbar p{font-size:12px;line-height:1.9;color:#8190a4;margin:7px 0 0}.master-actions{display:flex;gap:8px;flex-shrink:0}.master-actions .el-button+.el-button{margin-left:0}.master-filters{display:flex;align-items:center;gap:10px;margin-bottom:20px;flex-wrap:wrap}.master-filters>.el-input{width:260px}.master-filters>.el-select{width:160px}.master-filters>span{margin-left:auto;color:#8a97a8;font-size:12px}.cost-table-scroll{overflow:auto;max-width:100%}.cost-table{width:100%;min-width:840px;border-collapse:collapse;table-layout:fixed;font-size:13px;color:#4b5d74}.cost-table th{padding:12px;background:#f5f7fb;color:#7b899d;text-align:left;font-size:12px;font-weight:500;line-height:1.7}.cost-table td{padding:13px 12px;border-bottom:1px solid #e9edf3;line-height:1.8;overflow-wrap:anywhere}.cost-table tbody tr:hover{background:#fafbfd}.cost-table .numeric{text-align:right;font-variant-numeric:tabular-nums}.cost-table .action-cell{text-align:right;white-space:nowrap}.cost-table b{font-weight:600}.cost-table small{display:block;font-size:11px;color:#8b97a8;margin-top:3px;line-height:1.8}.text-link{border:0;background:none;padding:0;color:#2a5a91;cursor:pointer;text-align:left;font-size:13px;font-weight:600;line-height:1.8}.master-table th:first-child{width:22%}.master-table th:last-child{width:110px}.master-table th:nth-child(3){width:70px}.purchase-pending{color:#b78643;font-size:12px}.packaging-table{min-width:760px}.schemes-table{min-width:580px}.scheme-code{color:#8290a5;font-size:12px;font-variant-numeric:tabular-nums}.scheme-linked-count{font-weight:500}.linked-dishes-note{font-size:13px;color:#7d8da2;line-height:1.8;margin:0 0 16px}.linked-dishes-search{margin-bottom:18px}.linked-dishes-table{min-width:760px}.linked-dishes-table .text-link{font-size:12px}.cost-pagination{justify-content:flex-end;margin-top:20px}.source-caption{margin:18px 0 0;color:#8d99a9;font-size:11px;line-height:1.8}.workbench-error{font-size:13px;color:#b96744;line-height:1.8}.cost-dish-dialog :deep(.el-dialog__body){max-height:72vh;overflow:auto}@media(max-width:1100px){.master-toolbar{flex-direction:column;gap:12px}.master-panel{padding:18px}}@media(max-width:760px){.workbench-tabs{gap:16px}.workbench-toolbar{gap:8px}.master-actions{flex-wrap:wrap}.master-filters>.el-input{width:100%}.master-filters>.el-select{width:140px}.cost-pagination{justify-content:flex-start;overflow:auto}}
</style>
